function evaluate(b,side){let score=0;for(let r=0;r<8;r++)for(let c=0;c<8;c++){let p=b[r][c];if(p==='.')continue;let v=VALUE[p.toLowerCase()];let center=3.5-(Math.abs(3.5-r)+Math.abs(3.5-c))/2;if(p.toLowerCase()==='p')v+= (p==='P'?(6-r):(r-1))*5;if(p.toLowerCase()==='n'||p.toLowerCase()==='b')v+=center*9;score+=(color(p)===side?1:-1)*v}return score}
function aiMove(){if(gameOver||turn!=='b')return;thinking=true;let ms=movesFor(board,'b');if(!ms.length)return;let scored=ms.map(m=>{let cp=board.map(r=>r.slice()),capt=applyTo(cp,m),v=evaluate(cp,'b')-evaluate(board,'b');if(capt!=='.')v+=VALUE[capt.toLowerCase()]*.22;if(inCheck(cp,'w'))v+=45;if(inCheck(cp,'b'))v-=5;let [r,c]=m.to;v+=Math.random()*46; if(m.promotion)v+=700;return {m,v}}).sort((a,b)=>b.v-a.v);let best=scored.slice(0,Math.min(5,scored.length));let m=best[Math.floor(Math.random()*best.length)].m;thinking=false;commit(m,true)}
function squareName(r,c){return String.fromCharCode(97+c)+(8-r)}
function render(statusOverride){const boardEl=$('board');boardEl.innerHTML='';let side=turn==='w'?'w':'b',check=inCheck(board,side),king=findKing(board,side);let lm=lastMove?lastMove.flat().map(x=>x):[];let legalDests=new Set(legal.map(m=>m.to.join(',')));for(let vr=0;vr<8;vr++)for(let vc=0;vc<8;vc++){let r=flipped?7-vr:vr,c=flipped?7-vc:vc,p=board[r][c],sq=document.createElement('button');sq.className='square '+((r+c)%2?'dark':'light');sq.setAttribute('role','gridcell');sq.setAttribute('aria-label',`${squareName(r,c)}${p!=='.'?', '+(color(p)==='w'?'white':'black')+' '+pieceName(p):''}`);if(selected&&selected[0]===r&&selected[1]===c)sq.classList.add('selected');if(lastMove&&(lastMove[0][0]===r&&lastMove[0][1]===c||lastMove[1][0]===r&&lastMove[1][1]===c))sq.classList.add('last');if(check&&king&&king[0]===r&&king[1]===c)sq.classList.add('check');if(hintSquare&&hintSquare[0]===r&&hintSquare[1]===c)sq.style.boxShadow='inset 0 0 0 4px #80c892';if(legalDests.has(r+','+c)){let marker=document.createElement('i');marker.className=color(p)?'capture-ring':'dot';sq.append(marker)}if(p!=='.'){let piece=document.createElement('span');piece.className='piece '+(color(p)==='w'?'white':'black');piece.textContent=ICON[p];sq.append(piece)}if(vc===0){let coord=document.createElement('span');coord.className='coord';coord.textContent=8-r;sq.append(coord)}if(vr===7){let coord=sq.querySelector('.coord');if(!coord){coord=document.createElement('span');coord.className='coord';sq.append(coord)}coord.classList.add('filecoord');coord.textContent=squareName(r,c)[0]}sq.addEventListener('click',()=>onSquare(r,c));boardEl.append(sq)}
$('turnsDone').textContent=rounds;$('progressFill').style.width=`${rounds*10}%`;$('moveCounter').textContent='MOVE '+String(fullmove).padStart(2,'0');$('statusText').textContent=statusOverride|| (thinking?'Shadow is thinking…':turn==='w'?'Your move — choose a piece':'Shadow is thinking…');$('turnDot').style.background=turn==='w'?'#99bd8c':'#d99b6f';$('statusNote').textContent=gameOver?'Run complete':`${Math.max(0,10-rounds)} ${10-rounds===1?'turn':'turns'} to survive`;$('kingStatus').textContent=check?'KING UNDER CHECK':'KING’S VIGOR · '+(rounds<4?'STEADY':rounds<8?'WARY':'FALTERING');$('undoBtn').disabled=undoStack.length===0||gameOver;$('hintBtn').disabled=turn!=='w'||gameOver;renderCaptured();renderHistory()}
function pieceName(p){return ({k:'king',q:'queen',r:'rook',b:'bishop',n:'knight',p:'pawn'})[p.toLowerCase()]}
function renderCaptured(){for(let s of ['w','b']){let items=captured[s].map(p=>ICON[p]).join('');$('captured'+(s==='w'?'White':'Black')).textContent=items||'—';$('captured'+(s==='w'?'White':'Black')).style.opacity=items?'1':'.32'}}
function renderHistory(){let el=$('moves');if(!history.length){el.innerHTML='<div class="empty-moves">Every battle begins with a first move.</div>';return}let rows=[];for(let i=0;i<history.length;i+=2){let w=history[i],b=history[i+1];rows.push(`<div class="move-row"><span class="move-num">${w?.n||i/2+1}.</span><span class="move-san ${i===history.length-1?'recent':''}">${w?.san||''}</span><span class="move-san ${i+1===history.length-1?'recent':''}">${b?.san||''}</span></div>`)}el.innerHTML=rows.join('');el.scrollTop=el.scrollHeight}
function onSquare(r,c){if(gameOver||turn!=='w'||thinking)return;let p=board[r][c];if(selected){let m=legal.find(m=>m.from[0]===selected[0]&&m.from[1]===selected[1]&&m.to[0]===r&&m.to[1]===c);if(m){if(p==='.'&&board[selected[0]][selected[1]]==='P'&&r===0||p==='.'&&board[selected[0]][selected[1]]==='p'&&r===7||['P','p'].includes(board[selected[0]][selected[1]])&&(r===0||r===7)){openPromotion(m);return}commit(m);return}if(selected[0]===r&&selected[1]===c){selected=null;legal=[];render();return}}if(color(p)==='w'){selected=[r,c];legal=movesFor(board,'w').filter(m=>m.from[0]===r&&m.from[1]===c);render()}}
function openPromotion(m){const pop=$('promotion');pop.innerHTML='';let box=document.createElement('div');box.className='promo-box';for(let t of ['Q','R','B','N']){let b=document.createElement('button');b.textContent=ICON[t];b.setAttribute('aria-label','Promote to '+pieceName(t));b.onclick=()=>{pop.classList.remove('show');commit({...m,promotion:t})};box.append(b)}pop.append(box);pop.classList.add('show')}
function endGame(won,title,text){gameOver=true;thinking=false;render();$('resultEmoji').textContent=won?'♔':'♟';$('resultTitle').textContent=title;$('resultText').textContent=text;$('overlay').classList.add('show')}
function reset(){board=initial();turn='w';selected=null;legal=[];history=[];captured={w:[],b:[]};ep=null;castle={w:{k:true,q:true},b:{k:true,q:true}};halfmove=0;fullmove=1;rounds=0;gameOver=false;flipped=false;lastMove=null;undoStack=[];hintSquare=null;thinking=false;$('overlay').classList.remove('show');$('promotion').classList.remove('show');render('Your move — choose a piece')}
function showToast(t){let el=$('toast');el.textContent=t;el.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>el.classList.remove('show'),1800)}
$('restartBtn').onclick=()=>reset();$('resultRestart').onclick=()=>reset();$('flipBtn').onclick=()=>{flipped=!flipped;render()};$('undoBtn').onclick=()=>{if(!undoStack.length||gameOver)return;let old=undoStack.pop();if(old.turn==='w'&&turn==='w'&&old.rounds===rounds&&undoStack.length){old=undoStack.pop()}restore(old);showToast('Last turn rewound')};$('hintBtn').onclick=()=>{if(turn!=='w'||gameOver)return;let ms=movesFor(board,'w');if(!ms.length)return;let ranked=ms.map(m=>{let cp=board.map(r=>r.slice()),cap=applyTo(cp,m);let s=evaluate(cp,'w')-evaluate(board,'w')+(cap!=='.'?VALUE[cap.toLowerCase()]*.35:0)+(inCheck(cp,'b')?45:0);return {m,s}}).sort((a,b)=>b.s-a.s);let m=ranked[Math.floor(Math.random()*Math.min(3,ranked.length))].m;hintSquare=m.to;render();showToast('Try '+squareName(...m.from)+' → '+squareName(...m.to))};let muted=false;$('soundBtn').onclick=()=>{muted=!muted;$('soundBtn').textContent=muted?'♪':'♫';showToast(muted?'Sound off':'Sound on')};document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('promotion').classList.remove('show');selected=null;legal=[];render()}if(e.key.toLowerCase()==='u')$('undoBtn').click();if(e.key.toLowerCase()==='r')reset()});reset();
</script></body></html>

