+<!doctype html>
+<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#101513"><title>Chess Survival</title>
+<style>
+@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&family=Playfair+Display:wght@600;700&display=swap');
+:root{--bg:#101513;--panel:#171e1a;--line:#303a33;--muted:#87948b;--text:#f1f0e8;--gold:#e4b85e;--green:#99bd8c;--light:#e9dfc9;--dark:#66806c;--danger:#dd7869}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 48% -15%,#273329 0%,var(--bg) 57%);color:var(--text);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit;cursor:pointer}.app{max-width:1200px;margin:auto;padding:25px 38px 35px}.topbar{height:45px;display:flex;align-items:center;justify-content:space-between;margin-bottom:26px}.brand{display:flex;align-items:center;gap:12px;font-weight:800;letter-spacing:.08em;font-size:13px}.brandmark{width:34px;height:34px;border:1px solid #61745f;border-radius:10px;display:grid;place-items:center;color:var(--gold);font-size:21px}.brand small{display:block;color:var(--muted);font-weight:500;letter-spacing:.02em;font-size:10px;margin-top:3px}.topright{display:flex;align-items:center;gap:9px}.pill{border:1px solid var(--line);border-radius:100px;padding:8px 13px;color:#c0c9bd;font-size:11px;letter-spacing:.08em;text-transform:uppercase}.pill i{display:inline-block;width:6px;height:6px;background:#a4cd92;border-radius:50%;margin-right:7px;vertical-align:1px;box-shadow:0 0 8px #9dc18a}.iconbtn{background:transparent;border:1px solid var(--line);border-radius:10px;width:36px;height:36px;color:#aab4aa;font-size:15px}.hero{text-align:center;margin-bottom:24px}.eyebrow{font-family:'DM Mono',monospace;text-transform:uppercase;letter-spacing:.25em;font-size:10px;color:var(--gold);margin-bottom:8px}.hero h1{font-family:'Playfair Display',serif;font-size:clamp(29px,4vw,43px);line-height:1.08;margin:0;font-weight:600;letter-spacing:-.03em}.hero p{margin:9px 0 0;color:#9da79f;font-size:13px}.layout{display:grid;grid-template-columns:minmax(0,690px) 310px;gap:24px;align-items:start;justify-content:center}.board-side{min-width:0}.board-frame{padding:10px;background:#252e27;border:1px solid #435045;border-radius:9px;box-shadow:0 20px