41f,#171e1a);border:1px solid #303a33;border-radius:12px;padding:17px}.cardhead{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.cardtitle{font-size:10px;text-transform:uppercase;letter-spacing:.16em;color:#aeb8ad;font-weight:700}.cardicon{font-size:14px;color:var(--gold)}.survival-card{padding:20px}.survival-head{display:flex;align-items:center;justify-content:space-between}.survival-title{font-family:'Playfair Display',serif;font-size:19px}.wave-tag{font:10px 'DM Mono',monospace;color:var(--gold);border:1px solid #6d5934;border-radius:5px;padding:5px 7px}.progress-label{display:flex;justify-content:space-between;margin-top:19px;font-size:11px;color:#9ba69c}.progress-label b{color:#e7e5d9;font:11px 'DM Mono',monospace}.progress{height:5px;background:#303a33;border-radius:5px;margin-top:8px;overflow:hidden}.progress span{height:100%;display:block;width:0;background:linear-gradient(90deg,#9abd8b,#e2ba6a);border-radius:5px;transition:width .4s}.survive-copy{font-size:12px;color:#98a399;line-height:1.55;margin:13px 0 0}.kinglife{display:flex;align-items:center;gap:5px;color:var(--danger);font-size:15px;margin-top:14px}.kinglife span{font-size:10px;color:#9ca69c;margin-left:5px;letter-spacing:.03em}.captured{display:grid;gap:8px}.captured-row{display:flex;align-items:center;min-height:24px}.captured-label{width:57px;color:#849087;font-size:10px;text-transform:uppercase;letter-spacing:.08em}.captured-pieces{font-family:'DejaVu Sans',serif;font-size:19px;letter-spacing:1px}.captured-pieces.white{color:#fffaf0;text-shadow:0 1px 1px #000}.captured-pieces.black{color:#a7b6a4}.moves{max-height:168px;overflow:auto;padding-right:3px}.moves::-webkit-scrollbar{width:4px}.moves::-webkit-scrollbar-thumb{background:#465348;border-radius:3px}.move-row{display:grid;grid-template-columns:26px 1fr 1fr;gap:8px;padding:6px 2px;border-bottom:1px solid #29322c;font:11px 'DM Mono',monospace}.move-row:last-child{border-bottom:0}.move-num{color:#79867b}.move-san{color:#d9ddd3}.move-san.recent{color:var(--gold)}.empty-moves{color:#78857b;font-size:11px;padding:6px 0}.actions{display:grid;grid-template-columns:1fr 1fr;gap:8px}.action{border:1px solid #3b473d;background:#232c25;border-radius:8px;padding:10px 8px;font-size:11px;font-weight:600;transition:.15s}.action:hover{border-color:#788b71;background:#29352c}.action.primary{background:#dfb85f;color:#172019;border-color:#dfb85f}.action.primary:hover{background:#efca78}.action:disabled{opacity:.42;cursor:not-allowed}.tip{font-size:10px;color:#7f8c82;line-height:1.5;margin:1px 2px 0}.overlay{position:absolute;inset:0;display:none;align-items:center;justify-content:center;background:#101511c9;backdrop-filter:blur(4px);z-index:5}.overlay.show{display:flex}.result-box{max-width:290px;text-align:center;padding:25px 28px;background:#1a221c;border:1px solid #53634f;border-radius:14px;box-shadow:0 20px 50px #0008}.result-emoji{font-size:30px}.result-box h2{font-family:'Playfair Display',serif;font-size:26px;margin:9px 0 7px}.result-box p{color:#a1ada0;font-size:12px;line-height:1.5;margin:0 0 17px}.result-box button{border:0;background:var(--gold);color:#152018;font-weight:700;border-radius:7px;padding:10px 18px;font-size:12px}.promotion{position:absolute;inset:0;display:none;align-items:center;justify-content:center;background:#10151199;z-index:4}.promotion.show{display:flex}.promo-box{background:#1b241d;border:1px solid #59644f;border-radius:10px;padding:14px;display:flex;gap:8px}.promo-box button{width:48px;height:53px;border:1px solid #424e42;background:#263128;border-radius:7px;font:34px 'DejaVu Sans',serif}.promo-box button:hover{border-color:var(--gold)}.footer{margin-top:20px;text-align:center;color:#68756b;font:10px 'DM Mono',monospace;letter-spacing:.07em}.toast{position:fixed;left:50%;bottom:22px;transform:translate(-50%,20px);padding:10px 16px;background:#27352b;border:1px solid #56694f;border-radius:8px;color:#e8e9dc;font-size:12px;opacity:0;transition:.2s;pointer-events:none;z-index:10}.toast.show{opacity:1;transform:translate(-50%,0)}@keyframes pulse{50%{box-shadow:inset 0 0 0 8px #d9675855}}
 @media(max-width:940px){.app{padding:20px}.layout{grid-template-columns:minmax(0,1fr) 280px;gap:17px}.square .piece{font-size:clamp(28px,6vw,52px)}}@media(max-width:720px){.app{padding:13px 12px 25px}.topbar{margin-bottom:18px}.hero{margin-bottom:17px}.layout{display:flex;flex-direction:column;align-items:stretch;gap:13px}.board-side{width:min(100%,560px);margin:auto}.side{width:min(100%,560px);margin:auto;display:grid;grid-template-columns:1fr 1fr;align-items:start}.survival-card,.moves-card{grid-column:span 2}.card{padding:14px}.survival-card{padding:16px}.moves{max-height:110px}.board-frame{padding:7px}.square .piece{font-size:clamp(32px,10.5vw,58px)}.status-note{font-size:10px}.topright .pill{font-size:9px;padding:7px 9px}}@media(max-width:390px){.side{grid-template-columns:1fr}.side>*{grid-column:span 1!important}.square .coord{font-size:8px}}
